# cart.py
def total(prices, discount=0):
    if not 0 <= discount <= 1:
        raise ValueError("discount must be between 0 and 1")
    return round(sum(prices) * (1 - discount), 2)

# test_cart.py
import pytest
from cart import total

def test_total_adds_prices():
    assert total([1.5, 2.5]) == 4.0

def test_discount_is_applied():
    assert total([10, 10], discount=0.25) == 15.0

def test_rejects_bad_discount():
    with pytest.raises(ValueError, match="between 0 and 1"):
        total([10], discount=2)

@pytest.mark.parametrize("prices, expected", [
    ([], 0),
    ([1, 2, 3], 6),
    ([0.1, 0.2], 0.3),
])
def test_total_cases(prices, expected):
    assert total(prices) == expected

@pytest.fixture
def sample_prices():
    return [5, 10, 20]

def test_uses_fixture(sample_prices):      # the argument name selects the fixture
    assert total(sample_prices) == 35

def test_writes_file(tmp_path):            # built-in fixture
    path = tmp_path / "out.txt"
    path.write_text("hi", encoding="utf-8")
    assert path.read_text(encoding="utf-8") == "hi"
